using Microsoft.EntityFrameworkCore;

static async Task ReserveAsync(ShopDb db, int productId, int qty)
{
    // The transaction doesn't stop another request reading the same Stock
    await using var tx = await db.Database.BeginTransactionAsync();
    var product = await db.Products.SingleAsync(p => p.Id == productId);
    if (product.Stock < qty) throw new OutOfStockException(productId);
    product.Stock -= qty; // EF sends SET [Stock] = @p0, a constant
    await db.SaveChangesAsync();
    await tx.CommitAsync(); // Test, orders of 3 and 2: stock 10 -> 8
}

using Microsoft.EntityFrameworkCore;

static async Task ReserveAsync(ShopDb db, int productId, int qty)
{
    // Check and write in one statement; a second one waits for the row
    var updated = await db.Products
        .Where(p => p.Id == productId && p.Stock >= qty)
        .ExecuteUpdateAsync(s =>
            s.SetProperty(p => p.Stock, p => p.Stock - qty));
    if (updated == 0) throw new OutOfStockException(productId);
    // Test, orders of 3 and 2: stock 10 -> 5
}
